mod solution;

fn main() {
    let cases = [
    (r#"[5,2,10,4]"#, r#"5,3.5,5,4.5"#),
    (r#"[1,3]"#, r#"1,2"#),
    (r#"
[1,3]
"#, r#"1,2"#),
    (r#"  
[5,2,10,4]
  "#, r#"5,3.5,5,4.5"#),
    ];
    for (case_index, (input, expected)) in cases.iter().enumerate() {
        if solution::solve(input) != *expected {
            eprintln!("PRIVATE CASE {} FAILED", case_index + 1);
            std::process::exit(1);
        }
    }
    println!("PASS two-heap-median");
}
